function shell(title,sub=''){ $('#screen').innerHTML=`<div class="page"><div class="page-title"><div><small>SPRIX Physics</small><h1>${title}</h1><p>${sub}</p></div><img class="ministry" src="${PHYSICS.ministry}"></div></div>`; }
function showHome(){state.view='home';$('#screen').innerHTML=`<section class="hero"><div class="hero-copy"><span class="eyebrow">البكالوريا المصرية • الصف الثاني الثانوي</span><h1>SPRIX <span>Physics</span></h1><p>تعلّم الفيزياء من خلال الاستكشاف، المحاكاة، الفيديو، الحوار، التدريب والاختبار — وفق دروس المنهج.</p><div class="actions"><button onclick="showMap()">🧭 خريطة التعلم</button><button onclick="showLab()">🔬 المختبر الافتراضي</button><button onclick="showReview()">🧠 المراجعة النهائية</button></div></div><div class="hero-art"><div class="orbit"><span>⚛</span></div><b>اسأل • جرّب • قِس • فسّر</b><img src="${PHYSICS.char}"/></div></section>`;}
function showMap(){state.view='map';shell('خريطة التعلم','23 درسًا — فصلان من منهج الفيزياء المرفق'); let html=''; [lessons.slice(0,12),lessons.slice(12)].forEach((arr,u)=>{html+=`<section class="unit"><div class="unit-head"><span>الفصل ${u+1}</span><b>${arr.length} درسًا</b></div><h2>${u===0?'الميكانيكا':'الحركة التذبذبية والموجات'}</h2><div class="lesson-grid">${arr.map((t,i)=>{let ix=u?i+12:i;return `<button class="lesson-card" onclick="openLesson(${ix})"><strong>${ix+1}</strong><span>${esc(t)}</span><small>فيديو • تجربة • 25 سؤال</small></button>`}).join('')}</div></section>`}); $('.page').insertAdjacentHTML('beforeend',html);}
function openLesson(i){state.lesson=i;state.step=0;renderLesson();}
function renderLesson(){let i=state.lesson,[name,focus,formula,unit]=meta[i]; const steps=['اكتشف','شاهد واشرح','جرّب بنفسك','اختبر فهمك']; $('#screen').innerHTML=`<div class="lesson-room"><div class="room-top"><button onclick="showMap()">← الخريطة</button><span>الدرس ${i+1} من 23</span></div><div class="lesson-title"><small>${i<12?'الفصل الأول • الميكانيكا':'الفصل الثاني • الحركة التذبذبية والموجات'}</small><h1>${esc(lessons[i])}</h1><div class="stepper">${steps.map((s,k)=>`<span class="${k===state.step?'on':''}">${k+1}. ${s}</span>`).join('')}</div></div><div class="lesson-layout"><main class="lesson-main">${lessonStep(i)}</main><aside class="character-panel">${dialogue(i)}</aside></div><div class="bottom-actions"><button onclick="showMap()">خروج</button><button class="primary" onclick="nextLessonStep()">${state.step<3?'تابع →':'ابدأ اختبار الدرس'}</button></div></div>`;}
function dialogue(i){let [name,focus,formula]=meta[i];let lines=[['مستر ذرة',`خلينا نبدأ بسؤال: إيه اللي نقدر نلاحظه في ${name}؟`,PHYSICS.char],['فوتون',`أنا أتوقع إن ${focus} هتظهر بوضوح لما نغيّر المتغير في التجربة.`,PHOTON],['مستر ذرة',`ممتاز! دلوقتي نقارن النتيجة بالقانون: ${formula}.`,PHYSICS.char],['فوتون','وبعدها نحل أسئلة الدرس ونشوف هل فهمنا الفكرة فعلًا.',PHOTON]];return `<div class="talks">${lines.map((l,k)=>`<div class="talk ${k%2?'right':'left'}"><img src="${l[2]}"><div><b>${l[0]}</b><p>${esc(l[1])}</p><button onclick="speak(${JSON.stringify(l[1])})">🔊</button></div></div>`).join('')}</div>`;}
function lessonStep(i){let [name,focus,formula,unit]=meta[i];if(state.step===0)return `<div class="card"><span class="eyebrow">الملاحظة → التفسير</span><h2>${esc(name)}</h2><p>${esc(focus)}.</p><div class="concept-box"><b>صندوق المعادلة</b><code>${esc(formula)}</code><span>الوحدة/الكمية: ${esc(unit)}</span></div><div class="prediction"><b>توقع قبل التجربة:</b><p>غيّر المتغير في المحاكاة ثم لاحظ ماذا يحدث للكمية المرتبطة به.</p></div></div>`;if(state.step===1)return `<div class="card video-card"><span class="eyebrow">فيديو الشرح</span><h2>شرح سريع: ${esc(name)}</h2><video controls playsinline preload="metadata" src="${videos[i]}"></video><p>${esc(focus)}. أوقف الفيديو عندما تريد وسجّل ملاحظتك.</p></div>`;if(state.step===2)return experiment(i);return lessonQuiz(i);}
function experiment(i){let [name,focus,formula]=meta[i];const kind=i%8; if(kind===0)return `<div class="card experiment"><h2>🧭 محاكاة المتجهات</h2><p>حرّك السرعتين ولاحظ المتجه المحصل.</p><label>vA <input id="a" type="range" min="0" max="20" value="12" oninput="vecExp()"></label><label>vB <input id="b" type="range" min="0" max="20" value="5" oninput="vecExp()"></label><div id="expOut" class="result"></div></div>`;if(kind===1)return `<div class="card experiment"><h2>🎯 محاكاة المقذوف</h2><label>السرعة الابتدائية <input id="v" type="range" min="5" max="30" value="15" oninput="projExp()"></label><label>الارتفاع <input id="h" type="range" min="1" max="20" value="10" oninput="projExp()"></label><div id="expOut" class="result"></div></div>`;if(kind===2)return `<div class="card experiment"><h2>🔄 العزم والاتزان</h2><label>القوة F <input id="f" type="range" min="1" max="50" value="20" oninput="torqueExp()"></label><label>ذراع القوة d <input id="d" type="range" min="0.1" max="5" step="0.1" value="2" oninput="torqueExp()"></label><div id="expOut" class="result"></div></div>`;if(kind===3)return `<div class="card experiment"><h2>⚡ القدرة والكفاءة</h2><label>الشغل W <input id="w" type="range" min="10" max="1000" value="500" oninput="powerExp()"></label><label>الزمن t <input id="t" type="range" min="1" max="20" value="5" oninput="powerExp()"></label><div id="expOut" class="result"></div></div>`;if(kind===4)return `<div class="card experiment"><h2>💥 التصادم والزخم</h2><label>m₁ <input id="m1" type="range" min="1" max="10" value="2" oninput="momentumExp()"></label><label>v₁ <input id="v1" type="range" min="1" max="20" value="8" oninput="momentumExp()"></label><div id="expOut" class="result"></div></div>`;if(kind===5)return `<div class="card experiment"><h2>🌀 الحركة الدائرية</h2><label>السرعة v <input id="cv" type="range" min="1" max="20" value="10" oninput="circleExp()"></label><label>نصف القطر r <input id="r" type="range" min="0.5" max="10" step="0.5" value="2" oninput="circleExp()"></label><div id="expOut" class="result"></div></div>`;if(kind===6)return `<div class="card experiment"><h2>🌊 الموجة الجيبية</h2><label>التردد f <input id="wf" type="range" min="1" max="20" value="5" oninput="waveExp()"></label><label>الطول الموجي λ <input id="wl" type="range" min="0.2" max="5" step="0.1" value="2" oninput="waveExp()"></label><div id="expOut" class="result"></div></div>`;return `<div class="card experiment"><h2>🔭 البصريات</h2><label>البعد البؤري f <input id="of" type="range" min="5" max="50" value="20" oninput="opticExp()"></label><label>بعد الجسم u <input id="ou" type="range" min="30" max="100" value="50" oninput="opticExp()"></label><div id="expOut" class="result"></div></div>`;}
function setOut(t,good=true){let e=$('#expOut');if(e)e.innerHTML=`<b>${good?'النتيجة':'ملاحظة'}</b><br>${t}`;}function vecExp(){let a=+$('#a').value,b=+$('#b').value;setOut(`مقدار السرعة النسبية في الاتجاه نفسه = |${a}-${b}| = <b>${Math.abs(a-b).toFixed(1)} m/s</b>.`)}function projExp(){let v=+$('#v').value,h=+$('#h').value,g=9.8,t=Math.sqrt(2*h/g),x=v*t;setOut(`زمن السقوط ≈ <b>${t.toFixed(2)} s</b>، والمدى الأفقي ≈ <b>${x.toFixed(2)} m</b>.`)}function torqueExp(){let f=+$('#f').value,d=+$('#d').value;setOut(`τ = Fd = <b>${(f*d).toFixed(1)} N·m</b>.`)}function powerExp(){let w=+$('#w').value,t=+$('#t').value;setOut(`P = W/t = <b>${(w/t).toFixed(1)} W</b>.`)}function momentumExp(){let m=+$('#m1').value,v=+$('#v1').value;setOut(`p = mv = <b>${(m*v).toFixed(1)} kg·m/s</b>.`)}function circleExp(){let v=+$('#cv').value,r=+$('#r').value;setOut(`التسارع المركزي = v²/r = <b>${(v*v/r).toFixed(2)} m/s²</b>.`)}function waveExp(){let f=+$('#wf').value,l=+$('#wl').value;setOut(`v = fλ = <b>${(f*l).toFixed(2)} m/s</b>.`)}function opticExp(){let f=+$('#of').value,u=+$('#ou').value;let v=1/(1/f-1/u);setOut(`من 1/f = 1/u + 1/v ⇒ v ≈ <b>${v.toFixed(2)} cm</b>.`)}
function lessonQuiz(i){let q=lessonQuestions[i][state.qi||0];return `<div class="card quiz"><span class="eyebrow">اختبار الدرس</span><h2>سؤال ${((state.qi||0)+1)} من 25</h2><p class="qtext">${esc(q.q)}</p>${q.o.map((o,k)=>`<button class="option" onclick="answerLesson(${i},${k})">${esc(o)}</button>`).join('')}</div>`}
function answerLesson(i,k){let q=lessonQuestions[i][state.qi||0]; if(k===q.a)state.score++; state.qi=(state.qi||0)+1; if(state.qi>=25){let sc=state.score;state.qi=0;state.score=0;$('#screen').innerHTML=`<div class="result-page"><h1>🎉 انتهى اختبار الدرس</h1><div class="score">${sc} / 25</div><p>هذا الاختبار خاص بـ <b>${esc(lessons[i])}</b> فقط.</p><button class="primary" onclick="openLesson(${i})">إعادة الدرس</button><button onclick="showMap()">العودة للخريطة</button></div>`;}else renderLesson();}
function nextLessonStep(){if(state.step<2){state.step++;renderLesson();}else{state.step=3;state.qi=0;state.score=0;renderLesson();}}
function showLab(){shell('المختبر الافتراضي','أدوات ومحاكاة فيزيائية بدلًا من أدوات الكيمياء');$('#screen .page').insertAdjacentHTML('beforeend',`<div class="lab-tabs"><button onclick="labVector()">المتجهات</button><button onclick="labProjectile()">المقذوفات</button><button onclick="labCollision()">التصادم</button><button onclick="labSHM()">الاهتزاز</button><button onclick="labWave()">الموجات</button><button onclick="labOptics()">البصريات</button><button onclick="balanceEq()">معادلات/وحدات</button></div><div id="labArea" class="lab-area"></div>`);labVector();}
function labVector(){$('#labArea').innerHTML=`<div class="lab-card"><h2>🧭 جمع المتجهات</h2><p>أدخل مركبتي متجهين واحسب المحصلة.</p><div class="inputs"><input id="ax" type="number" value="3"><input id="ay" type="number" value="4"><input id="bx" type="number" value="2"><input id="by" type="number" value="-1"></div><button onclick="calcVecLab()">احسب</button><div id="labResult" class="result"></div></div>`}function calcVecLab(){let ax=+$('#ax').value,ay=+$('#ay').value,bx=+$('#bx').value,by=+$('#by').value;let x=ax+bx,y=ay+by;$('#labResult').innerHTML=`Rx=<b>${x}</b> ، Ry=<b>${y}</b> ، |R|=<b>${Math.hypot(x,y).toFixed(2)}</b> ، θ=<b>${(Math.atan2(y,x)*180/Math.PI).toFixed(1)}°</b>`}function labProjectile(){$('#labArea').innerHTML=`<div class="lab-card"><h2>🎯 حاسبة المقذوف</h2><input id="lv" type="number" value="20"><input id="la" type="number" value="45"><button onclick="calcProjLab()">احسب المدى</button><div id="labResult" class="result"></div></div>`}function calcProjLab(){let v=+$('#lv').value,a=+$('#la').value*Math.PI/180;$('#labResult').innerHTML=`R≈<b>${(v*v*Math.sin(2*a)/9.8).toFixed(2)} m</b>`}function labCollision(){$('#labArea').innerHTML=`<div class="lab-card"><h2>💥 حفظ الزخم</h2><input id="cm1" type="number" value="2"><input id="cv1" type="number" value="5"><input id="cm2" type="number" value="3"><input id="cv2" type="number" value="-2"><button onclick="calcColLab()">احسب الزخم الكلي</button><div id="labResult" class="result"></div></div>`}function calcColLab(){let p=+$('#cm1').value*+$('#cv1').value + +$('#cm2').value*+$('#cv2').value;$('#labResult').innerHTML=`Σp=<b>${p.toFixed(2)} kg·m/s</b>`}function labSHM(){$('#labArea').innerHTML=`<div class="lab-card"><h2>〰️ البندول الزنبركي</h2><input id="sm" type="number" value="0.5"><input id="sk" type="number" value="50"><button onclick="calcSHM()">احسب الزمن الدوري</button><div id="labResult" class="result"></div></div>`}function calcSHM(){let m=+$('#sm').value,k=+$('#sk').value;$('#labResult').innerHTML=`T=<b>${(2*Math.PI*Math.sqrt(m/k)).toFixed(3)} s</b>`}function labWave(){$('#labArea').innerHTML=`<div class="lab-card"><h2>🌊 الموجات</h2><input id="lf" type="number" value="5"><input id="ll" type="number" value="0.4"><button onclick="calcWaveLab()">احسب السرعة</button><div id="labResult" class="result"></div></div>`}function calcWaveLab(){let f=+$('#lf').value,l=+$('#ll').value;$('#labResult').innerHTML=`v=fλ=<b>${(f*l).toFixed(2)} m/s</b>`}function labOptics(){$('#labArea').innerHTML=`<div class="lab-card"><h2>🔭 العدسات</h2><input id="lfoc" type="number" value="10"><input id="lu" type="number" value="30"><button onclick="calcOptLab()">احسب v</button><div id="labResult" class="result"></div></div>`}function calcOptLab(){let f=+$('#lfoc').value,u=+$('#lu').value,v=1/(1/f-1/u);$('#labResult').innerHTML=`v=<b>${v.toFixed(2)}</b> (بنفس وحدة الإدخال)`}function balanceEq(){ $('#labArea').innerHTML=`<div class="lab-card"><h2>🧮 مدقق المعادلات والوحدات</h2><p>اكتب علاقة فيزيائية بصيغة بسيطة، والمنصة تتحقق من الصيغة الأساسية المتاحة.</p><input id="eq" placeholder="مثال: v=fλ"><button onclick="checkEq()">تحقق</button><div id="labResult" class="result"></div></div>`}function checkEq(){let e=$('#eq').value.replaceAll(' ','').toLowerCase();let ok=['v=fλ','v=fl','p=mv','p=w/t','fc=mv2/r','t=2π√(m/k)','t=2π√(l/g)'].includes(e);$('#labResult').innerHTML=ok?'<span class="correct">✓ صحيحة</span>':'<span class="wrong">✗ غير مطابقة للعلاقة الأساسية المسجلة</span>'}
function showReview(){shell('المراجعة النهائية','بنك شامل من 1000 سؤال على منهج الفيزياء كله');let used=JSON.parse(localStorage.getItem('sprixPhysicsUsed')||'[]');let remain=1000-used.length;$('#screen .page').insertAdjacentHTML('beforeend',`<div class="review-box"><div class="bank-stat"><b>${remain}</b><span>سؤال متبقٍ</span></div><p>اختر عددًا من الأسئلة. عند إنهاء مجموعة، تُسجل الأسئلة المستخدمة على هذا الجهاز ولا تُعاد في جلسة المراجعة التالية.</p><div class="review-actions">${[5,10,20,25,50,100].map(n=>`<button onclick="startReview(${n})">${n} سؤال</button>`).join('')}</div></div><div id="reviewArea"></div>`)}function startReview(n){let used=new Set(JSON.parse(localStorage.getItem('sprixPhysicsUsed')||'[]'));let pool=reviewBank.map((q,i)=>({q,i})).filter(x=>!used.has(x.i));if(pool.length<n){alert('لا يوجد عدد كافٍ من الأسئلة الجديدة.');return}pool.sort(()=>Math.random()-.5);state.reviewSet=pool.slice(0,n);state.reviewIndex=0;state.reviewScore=0;renderReview()}function renderReview(){let item=state.reviewSet[state.reviewIndex],q=item.q;$('#reviewArea').innerHTML=`<div class="card quiz"><h2>المراجعة ${state.reviewIndex+1} / ${state.reviewSet.length}</h2><p class="qtext">${esc(q.q)}</p>${q.o.map((o,k)=>`<button class="option" onclick="answerReview(${k})">${esc(o)}</button>`).join('')}</div>`}function answerReview(k){let item=state.reviewSet[state.reviewIndex],q=item.q;if(k===q.a)state.reviewScore++;let used=new Set(JSON.parse(localStorage.getItem('sprixPhysicsUsed')||'[]'));used.add(item.i);localStorage.setItem('sprixPhysicsUsed',JSON.stringify([...used]));state.reviewIndex++;if(state.reviewIndex>=state.reviewSet.length){$('#reviewArea').innerHTML=`<div class="result-page"><h1>انتهت مجموعة المراجعة</h1><div class="score">${state.reviewScore} / ${state.reviewSet.length}</div><button class="primary" onclick="showReview()">مجموعة جديدة</button></div>`}else renderReview()}
function showTalk(){shell('غرفة النقاش','مستر ذرة يساعدك على التفكير بصوت عالٍ');$('.page').insertAdjacentHTML('beforeend',`<div class="talk-room">${dialogue(0)}</div>`)}
function toggleSide(){document.body.classList.toggle('side-open')}
showHome();
